/**
 * Generate a registration read-back for views, formers, and reactions.
 * The output reports opened and tested names, cardinality behavior, declared
 * promises and path structure. `Reacting.readBack()`
 * returns the complete string, and registration also sends it to the logger.
 */
import { varNamesInPattern } from "./operation-footprint.js";
import { scheduleBlock } from "./schedule.js";
import { renderRoles, renderWhereOp } from "./render.js";
const PROMISE_WORDS = {
    one: "exactly one",
    optional: "at most one",
    many: "any number of",
};
/** The tested slots of a line: out entries that are literals or bound names. */
function testedSlots(op, opens) {
    const tested = [];
    for (const [key, value] of Object.entries(op.out)) {
        const names = varNamesInPattern({ value });
        if (names.length === 0 || names.some((name) => !opens.includes(name)))
            tested.push(key);
    }
    if ("not" in op && op.not !== undefined) {
        for (const key of Object.keys(op.not))
            tested.push(`not ${key}`);
    }
    return tested;
}
/** Describe what one line opens, tests, and does with cardinality. */
function construeOp(op, opens, env) {
    const parts = [];
    const opensPart = opens.length > 0 ? `opens (${opens.join(", ")})` : "";
    switch (op.op) {
        case "find":
        case "whether":
        case "no": {
            const promise = "view" in op && op.view !== undefined
                ? (env.viewPromise(op.view) ?? undefined)
                : op.query !== undefined
                    ? env.queryPromise(op.query)
                    : undefined;
            const tested = testedSlots(op, opens);
            if (op.op === "no") {
                parts.push("holds only when no such row exists — drops the case otherwise");
                break;
            }
            if (op.op === "whether") {
                parts.push(opens.length > 0
                    ? `binds or leaves blank (${opens.join(", ")} possibly blank)`
                    : "proceeds either way");
                if (promise === "many" && opens.length > 0)
                    parts.push("fans out per match");
                break;
            }
            if (opens.length === 0) {
                parts.push("existence — fires once or drops the case");
                break;
            }
            if (promise === "one")
                parts.push("always fills");
            else if (promise === "optional")
                parts.push("fills or drops the case");
            else
                parts.push("fans out once per distinct fill");
            if (opensPart !== "")
                parts.push(opensPart);
            if (tested.length > 0)
                parts.push(`tests (${tested.join(", ")}) — may drop the case`);
            break;
        }
        case "holds":
            parts.push("tests — drops the case when it does not hold");
            break;
        case "compute":
            parts.push(`computes (${typeof op.out === "string" ? op.out : varNamesInPattern(op.out).join(", ")})`);
            break;
        case "count":
            parts.push(`counts into (${op.out}) — always fills`);
            break;
        case "custom":
            parts.push("opaque code — the read-back cannot see inside");
            break;
        case "earlier":
            parts.push("reads the flow's record, once per matching occurrence");
            break;
        case "now":
            parts.push(`opens (${op.out}) from the flow's outermost occurrence`);
            break;
    }
    return parts.join("; ");
}
function triggerOpens(trigger) {
    const names = trigger.kind === "channel"
        ? varNamesInPattern(trigger.pattern)
        : [...varNamesInPattern(trigger.input), ...varNamesInPattern(trigger.output)];
    return [...new Set(names)];
}
/** Generate one reaction's line-by-line read-back. */
export function readBackReaction(reaction, env) {
    const lines = [`${reaction.name}`];
    const bound = new Set();
    for (const trigger of reaction.when) {
        const opens = triggerOpens(trigger).filter((name) => !bound.has(name));
        for (const name of opens)
            bound.add(name);
        const head = trigger.kind === "channel"
            ? `any action ${trigger.channel}`
            : `${trigger.concept}.${trigger.action}`;
        lines.push(`  when ${head}${opens.length > 0 ? ` — opens (${opens.join(", ")})` : ""}`);
    }
    if (reaction.deferred === true) {
        lines.push("  at the flow's settlement frontier — after tracked ordinary work in this causal flow drains");
    }
    const scheduled = scheduleBlock(reaction.where, bound, `Reaction "${reaction.name}"`);
    for (const op of scheduled.ordered) {
        const opens = scheduled.opens.get(op) ?? [];
        lines.push(`  ${renderWhereOp(op)} — ${construeOp(op, opens, env)}`);
    }
    for (const consequence of reaction.then) {
        lines.push(`  then ${consequence.concept}.${consequence.action} (${renderRoles(consequence.input)})`);
    }
    return lines.join("\n");
}
/** Generate one view's declared promise and inferred body bound. */
function readBackView(view, env) {
    const lines = [];
    const partitions = [
        view.ins.length > 0 ? `inputs (${view.ins.join(", ")})` : "inputs ()",
        view.outs.length > 0 ? `outputs (${view.outs.join(", ")})` : "outputs ()",
        view.bindings.length > 0 ? `bindings (${view.bindings.join(", ")})` : "bindings ()",
    ].join("; ");
    const head = `${view.name} — ${partitions}`;
    if (view.holds === true) {
        lines.push(`${head} — a predicate: holds or not`);
    }
    else {
        const promise = view.promise;
        const declared = `promises ${PROMISE_WORDS[promise]} (${view.outs.join(", ")})`;
        lines.push(`${head} — ${declared}; checked when read`);
    }
    const ins = view.ins;
    for (const block of view.alternatives) {
        const initial = new Set(ins);
        const scheduled = scheduleBlock(block, initial, `View "${view.name}"`);
        for (const op of scheduled.ordered) {
            const opens = scheduled.opens.get(op) ?? [];
            lines.push(`  ${renderWhereOp(op)} — ${construeOp(op, opens, env)}`);
        }
    }
    return lines.join("\n");
}
function readBackFormer(former) {
    const partitions = [
        former.ins.length > 0 ? `inputs (${former.ins.join(", ")})` : "inputs ()",
        former.bindings.length > 0 ? `bindings (${former.bindings.join(", ")})` : "bindings ()",
    ].join("; ");
    return `${former.name} — ${partitions}; promises ${PROMISE_WORDS[former.promise]}; checked when formed`;
}
/** The whole application's read-back: every view, then every reaction. */
export function readBackApp(views, formers, reactions, unlowered, env) {
    const sections = [];
    for (const view of views)
        sections.push(readBackView(view, env));
    for (const former of formers)
        sections.push(readBackFormer(former));
    for (const reaction of reactions)
        sections.push(readBackReaction(reaction, env));
    for (const reaction of unlowered) {
        sections.push(`${reaction.name}\n  local executable reaction${reaction.known.deferred === true ? " at the flow's settlement frontier" : ""} — not portable\n  reason — ${reaction.reason}`);
    }
    return sections.join("\n\n");
}
